/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    let routeParam = api.context.props.route;

    switch (routeParam) {
        case ("user-roles"):
            {
                return {
                    params: {
                        "parentRoute": "operational-success"
                    },
                    route: "user-roles",
                    fields: null
                };
            }
        case ("tabs-and-dashboards"):
            {
                return {
                    params: {
                        "parentRoute": "operational-success",
                        "serviceGroup": api.context.props.serviceGroup
                    },
                    route: "tabs-and-dashboards",
                    fields: null
                };
            }
        case ("dashboard-visualizations"):
            {
                return {
                    params: null,
                    route: "dashboard-visualizations",
                    fields: {
                        "dashboardId": api.context.props.dashboardId
                    }
                };
            }
    }
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 */
function evaluateEvent({
    api,
    event
}) {
    var res = {};
    Object.keys(api.context.props).forEach(function(propName) {
        if (api.context.props[propName])
            res[propName] = api.context.props[propName];
    });
    return {
        propName: "pageParams",
        value: res
    };
}

